import http.server,socketserver,json
class H(http.server.BaseHTTPRequestHandler):
    protocol_version='HTTP/1.1'
    def _h(self):
        l=int(self.headers.get('Content-Length') or 0); b=self.rfile.read(l).decode('latin1') if l else ''
        p=json.dumps({'method':self.command,'path':self.path,'headers':dict(self.headers),'body':b},sort_keys=True).encode()
        self.send_response(200); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(p))); self.end_headers(); self.wfile.write(p)
    def do_GET(self): self._h()
    def do_POST(self): self._h()
    def do_PUT(self): self._h()
    def log_message(self,*a): pass
with socketserver.TCPServer(('127.0.0.1',0),H) as s: print(s.server_address[1],flush=True); s.serve_forever()
